--一次
function UIJackpotDungoenExchangeDialog:OnBtnOneDraw()
    if not HalloweenUtils.IsOpen() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end

    local isUnlock = HalloweenUtils.IsUnlockRewardPool(self._curPoolId)
    if not isUnlock then
        GameUtils.Toast(localize("该卡池未解锁"))
        return
    end

    local isFinish = HalloweenUtils.IsRewardPoolFinish(self._curPoolId)
    if not isUnlock then
        GameUtils.Toast(localize("该卡池已抽完"))
        return
    end

    local vo = HalloweenUtils.GetHalloweenRewardPoolVo(self._curPoolId)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.consumeId)
    if GoodsUtils.GetThingNo(vo.consumeId) < checkNumber(vo.consumeNumSingle) then
        --GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
        GoodsUtils.CheckConsumeDataCondition({
            {
                goodsId = checkNumber(vo.consumeId),
                num = checkNumber(vo.consumeNumSingle),
            }
        })
        return  
    end

    local num = 1
    comp:ActivityGashaponQuestChallengeCallReq(self._curPoolId, 1, function()
        GoodsUtils.DrawRewards({
            {
                goodsId = vo.consumeId,
                num = -checkNumber(vo.consumeNumSingle),
            }
        }, true)

        self:FillPools()
        self:FillPoolInfo()
        self:FillRewards()
    end, num)
end

--十连
function UIJackpotDungoenExchangeDialog:OnBtnTenDraw()
    if not HalloweenUtils.IsOpen() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end

    local isUnlock = HalloweenUtils.IsUnlockRewardPool(self._curPoolId)
    if not isUnlock then
        GameUtils.Toast(localize("该卡池未解锁"))
        return
    end

    local isFinish = HalloweenUtils.IsRewardPoolFinish(self._curPoolId)
    if not isUnlock then
        GameUtils.Toast(localize("该卡池已抽完"))
        return
    end

    local num = HalloweenUtils.GetDrawNum(self._curPoolId)

    local vo = HalloweenUtils.GetHalloweenRewardPoolVo(self._curPoolId)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.consumeId)

    local consumeNum = num * checkNumber(vo.consumeNumSingle)
    if GoodsUtils.GetThingNo(vo.consumeId) < consumeNum then
        GoodsUtils.CheckConsumeDataCondition({
            {
                goodsId = checkNumber(vo.consumeId),
                num = checkNumber(consumeNum),
            }
        })
        
        --GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
        return  
    end

    comp:ActivityGashaponQuestChallengeCallReq(self._curPoolId, 2, function()
        GoodsUtils.DrawRewards({
            {
                goodsId = vo.consumeId,
                num = -checkNumber(consumeNum),
            }
        }, true)

        self:FillPools()
        self:FillPoolInfo()
        self:FillRewards()
    end, num)
end

