function UIJackpotDungoenExchangeDialog:FillTime()
    local scr = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
    if scr then
        local vo = HalloweenUtils.GetHalloweenPlanVo(self._activityId)
        xTry(function()
            local skinId = vo.showCard
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(skinId)
            if not isNull(goodsVo) then
                local idType = GoodsUtils.GetIdType(goodsVo.id)
                if idType == Constants.IDType.CardSkin then
                    if scr then
                        scr:RefreshSelf(vo.showCard, goodsVo.quality, function()
                            xRecord.record('10-006', "activity_page_click_"..HalloweenUtils.GetUuid().."_"..7)
                        end, true)
                    end
                else
                    ---@type CardVo
                    local cardVo = CfUtils.GetCfVo(AutoIds.IdSetting28, "CardVo", vo.showCard)
                    scr:RefreshSelf(vo.showCard, cardVo.rare, function()
                        xTry(function()
                            ---@type GachaponUtils
                            local GachaponUtils = import('Game.Gachapon.GachaponUtils')
                            GachaponUtils.OpenDetail(vo.showCard, {{ id = Constants.UITypeIds.UIJackpotDungoenExchangeDialog}})
                        end)
                    end, false)
                end
            end
            
            
            
            
            
     --[[       scr:RefreshSelf(vo.showCard, nil, function(showCard)
                xRecord.record('10-006', "activity_page_click_"..HalloweenUtils.GetUuid().."_"..7)

                local GachaponUtils = import('Game.Gachapon.GachaponUtils')
                GachaponUtils.OpenDetail(showCard, { { id = Constants.UITypeIds.UIJackpotDungoenExchangeDialog } })
            end)]]
        end)
    end

    local t = ActivityMgr:GetInstance():GetActivityData()
    if not t then
        return
    end

    local data = nil
    local uuId = HalloweenUtils.GetUuid()
    for k, v in pairs(t) do
        if checkInt(v.type) == ActivityConstants.ActivityType.HalloweenQuest and checkNumber(v.id) == checkNumber(uuId) then
            data = v
            break
        end
    end

    if data then
        CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(data.startTime, data.endTime))
    end
end

function UIJackpotDungoenExchangeDialog:ChangePool(poolId)
    if checkNumber(poolId) <= 0 then 
        return
    end

    self._curPoolId = checkNumber(poolId)
    self:FillPools()

    self:FillPoolInfo()
    self:FillRewards()

    KCookie.Set("UIJackpotDungoenExchangeDialogLastPoolId", checkNumber(poolId))
end

function UIJackpotDungoenExchangeDialog:FillPoolInfo()
    local vo = HalloweenUtils.GetHalloweenRewardPoolVo(self._curPoolId)
    if vo then
        if checkNumber(vo.total) == -1 then
            CfUtils.SetActive(self.PanelGroup.transform:Find("TxtStock"), false)
        else
            CfUtils.SetActive(self.PanelGroup.transform:Find("TxtStock"), true)
            local num = HalloweenUtils.GetRewardPoolDrawNum(self._curPoolId)
            CfUtils.FillText(self.TxtNum, "<color=#ff8400>"..(checkNumber(vo.total) - checkNumber(num)).."</color>/"..vo.total)
        end
    end

    local isUnlock = HalloweenUtils.IsUnlockRewardPool(self._curPoolId)
    local isFinish = HalloweenUtils.IsRewardPoolFinish(self._curPoolId)
    
    CfUtils.SetActive(self.BtnExchangeGroup, isUnlock and not isFinish)
    CfUtils.SetActive(self.TxtTips_Empty, isFinish)
    CfUtils.SetActive(self.TxtTips_Lock,  not isUnlock)
    ---现在没有剧情  直接隐藏掉
    CfUtils.SetActive(self.BtnOpen, false)

    CfUtils.SetActive(self.BtnExchange2.transform:Find("CommonBtnConsumePop"), true)
    CfUtils.SetActive(self.BtnExchange1.transform:Find("CommonBtnConsumePop"), true)

    local drawNum = HalloweenUtils.GetDrawNum(self._curPoolId)
    CfUtils.FillCommonBtnConsumePopNode(self.BtnExchange2.transform:Find("CommonBtnConsumePop"), vo.consumeId, drawNum * checkNumber(vo.consumeNumSingle))
    CfUtils.FillCommonBtnConsumePopNode(self.BtnExchange1.transform:Find("CommonBtnConsumePop"), vo.consumeId, checkNumber(vo.consumeNumSingle))

    CfUtils.FillText(self.BtnExchange2.transform:Find("TxtExchange"), localize("兑换_num_次", {_num_ = drawNum}))
end

function UIJackpotDungoenExchangeDialog:FillRewards()
    local t = {
        {
            type = 1,
            name = localize("限定奖励"),
            data = HalloweenUtils.GetPoolAllReward(self._curPoolId, 1),
        },
        {
            type = 2,
            name = localize("普通奖励"),
            data = HalloweenUtils.GetPoolAllReward(self._curPoolId, 2),
        },
    }

    for k, v in pairs(t) do
        local go = self.Content.transform:Find("Cell"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.Cell, self.Content)
            go.name = "Cell"..k
        end

        self:FillReward(go, v)
        CfUtils.SetActive(go, true)
    end
end

function UIJackpotDungoenExchangeDialog:FillReward(go, data)
    if not go or not data then
        return
    end

    CfUtils.SetUISwitchText(go.transform:Find("title/name"), data.type)

    local vo = HalloweenUtils.GetHalloweenRewardPoolVo(self._curPoolId)
    if checkNumber(vo.total) < 0 then
        if data.type == 1 then
            CfUtils.FillText(go.transform:Find("title/TxtStatistics"), vo.displayProRare)
        else
            CfUtils.FillText(go.transform:Find("title/TxtStatistics"), vo.displayProNormal)
        end
    else
        local num1, num2 = HalloweenUtils.GetReardsNum(self._curPoolId, data.type)
        CfUtils.FillText(go.transform:Find("title/TxtStatistics"), num2.."/"..num1)
    end

    local t = data.data

    local itemPar = go.transform:Find("items")
    local itemGo = itemPar.transform:Find("FightRewardNode")
    for i = 1, table.count(t) do
        local goodsGo = itemPar.transform:Find("go"..i)
        if not goodsGo then
            goodsGo = CfUtils.InstantiateGo(itemGo, itemPar)
            goodsGo.name = "go"..i
        end

        local vo = HalloweenUtils.GetHalloweenPoolRewardVo(t[i])

        CfUtils.RefeshGoodGo2(goodsGo.transform:Find("goodPar/GoodNode"), vo.reward, vo.rewardNum, nil, nil, function()
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.reward)
            GameUtils.ShowCommonTipsBoard(goodsGo, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end)

        local drawNum = HalloweenUtils.GetRewardDrawNum(t[i])

        local isShow = false
        if checkNumber(vo.stock) < 0 then
            CfUtils.FillText(goodsGo.transform:Find("SurplusGroup/TxtNum"), "∞")
            isShow = (checkNumber(vo.reward) == 900302)
        else
            CfUtils.FillText(goodsGo.transform:Find("SurplusGroup/TxtNum"), checkNumber(vo.stock) - drawNum)
            isShow = ((checkNumber(vo.reward) == 900302) and ((checkNumber(vo.stock) - drawNum) > 0)) 
        end

        local status = (((checkNumber(vo.stock) - drawNum) == 0) and 2 or 1)
        CfUtils.SetUISwitchImage(goodsGo.transform:Find("SurplusGroup"), status)
        local grayGraphics = goodsGo.transform:Find("goodPar/GoodNode/Container"):GetComponent(UIGrayGraphics)
        if not isNull(grayGraphics) then
            grayGraphics:MarkGray((checkNumber(vo.stock) - drawNum) == 0)
        end

        CfUtils.SetActive(goodsGo.transform:Find("goodPar/UIFX_Jackpot_Exchange_Goods_Light"), isShow)

        CfUtils.SetActive(goodsGo, true)
    end

    local childCount = itemPar.transform.childCount
    if table.count(t) < childCount then
        for i = table.count(t) + 1, childCount do
            local goodsGo = itemPar.transform:Find("go"..i)
            if not isNull(goodsGo) then
                CfUtils.SetActive(goodsGo, false)
            end
        end
    end
end 

function UIJackpotDungoenExchangeDialog:FillBtns()
    local ind = table.indexof(self._allPool, checkString(self._curPoolId))
    if checkNumber(ind) > 0 then
        CfUtils.SetActive(self.BtnArrowLeft, ind ~= 1)
        CfUtils.SetActive(self.BtnArrowRight, ind ~= table.count(self._allPool))
    end
end

function UIJackpotDungoenExchangeDialog:OnBtnArrowRight()
    local ind = checkNumber(table.indexof(self._allPool, checkString(self._curPoolId)))
    if checkNumber(ind) <= 0 then
        return
    end

    if ind >= table.count(self._allPool) then
        return
    end

    self:ChangePool(self._allPool[ind + 1])
    self:FillBtns()
end

function UIJackpotDungoenExchangeDialog:OnBtnArrowLeft()
    local ind = checkNumber(table.indexof(self._allPool, checkString(self._curPoolId)))
    if checkNumber(ind) <= 0 then
        return
    end

    if ind <= 1 then
        return
    end

    self:ChangePool(self._allPool[ind - 1])
    self:FillBtns()
end

function UIJackpotDungoenExchangeDialog:FillPools()
    for i = 1, #self._allPool do
        local go = self.PageIdentification.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.Group, self.PageIdentification)
            go.name = "go"..i
        end

        self:FillPoolPoint(go , self._allPool[i])
    end
end

function UIJackpotDungoenExchangeDialog:FillPoolPoint(go, id)
    if not go or not id then
        return
    end

    local isUnlock = HalloweenUtils.IsUnlockRewardPool(id)
    local isFinish = HalloweenUtils.IsRewardPoolFinish(id)

    local status = 1
    if isUnlock and not isFinish then
        if checkNumber(self._curPoolId) == checkNumber(id) then
            status = 2
        end
    else
        if checkNumber(self._curPoolId) == checkNumber(id) then
            status = 4
        else
            status = 3
        end
    end
    CfUtils.SetUISwitchImage(go.transform:Find("ImgIcon"), status)

    CfUtils.SetActive(go.transform:Find("ImgState"), not isUnlock or isFinish)
    if not isUnlock or isFinish then
        status = 1
        if isFinish then
            status = 2
        else
            if checkNumber(self._curPoolId) == checkNumber(id) then
                status = 3
            end
        end
    end
    CfUtils.SetUISwitchImage(go.transform:Find("ImgState"), status)

    CfUtils.SetActive(go, true)
end

function UIJackpotDungoenExchangeDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if argument then
            self._activityId = checkNumber(argument.activityId)  
        end

        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

function UIJackpotDungoenExchangeDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIJackpotDungoenExchangeDialog
